import re

__author__ = 'Marcin Siedlarz'


def convert_data(parsed_data):
    '''
    '''
    if parsed_data == 'NULL':
        return None
    elif parsed_data in ['inf', 'infinity']:
        return 'inf'
    else:
        return convert_valid_data(parsed_data)


def convert_valid_data(data):
    '''
    '''
    if data.isdigit():
        return int(data)
    try:
        return float(data)
    except ValueError:
        pass
    hex_expression = re.match(r"'(\w+)'H", data)
    if hex_expression is not None:
        return '0x' + hex_expression.group(1)
    bin_expression = re.match(r"'([ 01]+)'B", data)
    if bin_expression is not None:
        return '0b' + re.sub(' ', '', bin_expression.group(1))
    # not able to enable due to backward-compatibility feature
    # duble_qoute_expression = re.match(r"\".*?\"", data)
    # if duble_qoute_expression is not None:
    #     return re.sub(r"\"", '', data)
    return data
